-- Судится открытая версия (и закрытые): задачи и требования следующей и поздних
-- версий её не держат (решение владельца 2026-10-07). Без открытой версии — весь набор.
SELECT t.id || ' — не названы операции: ' || string_agg(DISTINCT ro.operation, ', ') AS detail FROM project_plan_tasks t JOIN task_requirement tr ON tr.project_id = t.project_id AND tr.task_id = t.id JOIN project_requirement_op ro ON ro.project_id = t.project_id AND ro.requirement_id = tr.requirement_id LEFT JOIN project_task_operation tо ON tо.project_id = t.project_id AND tо.task_id = t.id AND tо.operation = ro.operation WHERE t.project_id = $1 AND t.kind = 'dev' AND NOT EXISTS (SELECT 1 FROM task_scope sc WHERE sc.project_id = t.project_id AND sc.task_id = t.id AND sc.scope IN ('next','later')) AND tо.operation IS NULL GROUP BY t.id ORDER BY t.id
